INSERT INTO services (code, name, service_line, description) VALUES ('AUD-001', 'Financial Statement Audit', 'Audit & Assurance', 'An independent review of your company''s financial records to give you — and your stakeholders — confidence that the numbers are accurate and trustworthy.');
INSERT INTO services (code, name, service_line, description) VALUES ('AUD-002', 'Review Engagement', 'Audit & Assurance', 'A lighter-touch review of your financials that provides limited assurance — ideal when a full audit isn''t required but stakeholders still want comfort.');
INSERT INTO services (code, name, service_line, description) VALUES ('AUD-003', 'Internal Control Review', 'Audit & Assurance', 'We examine the systems and processes that protect your business, identifying weaknesses before they become problems.');
INSERT INTO services (code, name, service_line, description) VALUES ('AUD-004', 'Agreed-Upon Procedures', 'Audit & Assurance', 'Targeted checks on specific areas like AML/CFT compliance, IT systems, or client fund handling — tailored to exactly what you need verified.');
INSERT INTO services (code, name, service_line, description) VALUES ('AUD-005', 'Capital Adequacy Review', 'Audit & Assurance', 'We verify that your company maintains the required capital levels, helping you stay compliant with regulatory requirements.');
INSERT INTO services (code, name, service_line, description) VALUES ('AUD-006', 'Fixed Assets & Inventory Verification', 'Audit & Assurance', 'A thorough physical count and valuation of your assets and inventory, ensuring your records match what''s actually on the ground.');
INSERT INTO services (code, name, service_line, description) VALUES ('AUD-007', 'Quality Assessment Review', 'Audit & Assurance', 'An objective evaluation of your internal audit function to ensure it meets professional standards and delivers real value.');
INSERT INTO services (code, name, service_line, description) VALUES ('IA-001', 'Outsourced Internal Audit', 'Internal Audit & Governance', 'Let our experienced team serve as your dedicated internal audit function — providing independent oversight without the overhead of building an in-house team.');
INSERT INTO services (code, name, service_line, description) VALUES ('IA-002', 'Co-Sourced Internal Audit', 'Internal Audit & Governance', 'We work alongside your existing internal audit team, providing specialized expertise and additional capacity when you need it most.');
INSERT INTO services (code, name, service_line, description) VALUES ('IA-003', 'Internal Audit Function Setup', 'Internal Audit & Governance', 'We help you build your internal audit department from the ground up — from hiring to methodology to reporting frameworks.');
INSERT INTO services (code, name, service_line, description) VALUES ('IA-004', 'Audit Charter & Manual Development', 'Internal Audit & Governance', 'We create the foundational documents that define your internal audit function''s purpose, authority, and operating procedures.');
INSERT INTO services (code, name, service_line, description) VALUES ('RISK-001', 'Enterprise Risk Management', 'Risk Advisory', 'A comprehensive approach to identifying and managing all the risks your organization faces — so you can make better decisions with confidence.');
INSERT INTO services (code, name, service_line, description) VALUES ('RISK-002', 'Risk Framework & Registers', 'Risk Advisory', 'We build the tools and frameworks you need to systematically track, assess, and respond to risks across your organization.');
INSERT INTO services (code, name, service_line, description) VALUES ('RISK-003', 'Business Continuity Planning', 'Risk Advisory', 'Prepare your organization to keep operating through disruptions — from natural disasters to system failures — with a clear, tested plan.');
INSERT INTO services (code, name, service_line, description) VALUES ('RISK-004', 'Related-Party Transaction Review', 'Risk Advisory', 'An independent review of transactions between related parties to ensure they''re conducted at arm''s length and properly disclosed.');
INSERT INTO services (code, name, service_line, description) VALUES ('TAX-001', 'Income Tax Filing', 'Tax Services', 'We handle the preparation and filing of your corporate income tax returns, ensuring accuracy and compliance with all deadlines.');
INSERT INTO services (code, name, service_line, description) VALUES ('TAX-002', 'Zakat Declaration', 'Tax Services', 'Expert preparation and submission of your Zakat declarations, ensuring compliance with Islamic finance principles and local regulations.');
INSERT INTO services (code, name, service_line, description) VALUES ('TAX-003', 'FATCA Assurance', 'Tax Services', 'We help you meet your Foreign Account Tax Compliance Act obligations, ensuring your reporting is accurate and on time.');
INSERT INTO services (code, name, service_line, description) VALUES ('TAX-004', 'CRS Assurance', 'Tax Services', 'Stay compliant with the Common Reporting Standard by ensuring your automatic exchange of financial account information is properly handled.');
INSERT INTO services (code, name, service_line, description) VALUES ('TAX-005', 'VAT Advisory', 'Tax Services', 'Expert guidance on Value Added Tax implementation, compliance, and optimization to minimize your tax burden legally.');
INSERT INTO services (code, name, service_line, description) VALUES ('TAX-006', 'Tax Consulting & Planning', 'Tax Services', 'Strategic tax advice to help you structure your business and transactions in the most tax-efficient way possible.');
INSERT INTO services (code, name, service_line, description) VALUES ('DEAL-001', 'Feasibility Study', 'Deal Advisory', 'Before you invest, we help you understand whether your project is commercially viable — with clear financial projections and market analysis.');
INSERT INTO services (code, name, service_line, description) VALUES ('DEAL-002', 'Business Valuation', 'Deal Advisory', 'Find out what your business is really worth — whether you''re planning a sale, seeking investment, or making strategic decisions.');
INSERT INTO services (code, name, service_line, description) VALUES ('DEAL-003', 'Investment Valuation', 'Deal Advisory', 'Get an independent, defensible valuation of your investment portfolio or specific assets to support informed decision-making.');
INSERT INTO services (code, name, service_line, description) VALUES ('DEAL-004', 'Mergers & Acquisitions Advisory', 'Deal Advisory', 'End-to-end support for buying, selling, or merging businesses — from initial strategy through deal close and integration.');
INSERT INTO services (code, name, service_line, description) VALUES ('DEAL-005', 'Due Diligence', 'Deal Advisory', 'A thorough investigation of a target company before you commit — covering financial, operational, and compliance risks.');
INSERT INTO services (code, name, service_line, description) VALUES ('DEAL-006', 'Boursa Kuwait Listing Advisory', 'Deal Advisory', 'Navigate the listing process with confidence — from eligibility assessment through IPO preparation and regulatory approvals.');
INSERT INTO services (code, name, service_line, description) VALUES ('FIN-001', 'Forensic Review & Fraud Examination', 'Financial & Accounting Advisory', 'When something doesn''t add up, our specialists investigate financial irregularities and help you understand what happened and how to prevent it.');
INSERT INTO services (code, name, service_line, description) VALUES ('FIN-002', 'Accounting System Design', 'Financial & Accounting Advisory', 'We design accounting systems tailored to your business needs, ensuring your financial data flows smoothly and reporting is effortless.');
INSERT INTO services (code, name, service_line, description) VALUES ('FIN-003', 'Chart of Accounts Design', 'Financial & Accounting Advisory', 'A well-structured chart of accounts is the foundation of good reporting — we design one that grows with your business.');
INSERT INTO services (code, name, service_line, description) VALUES ('FIN-004', 'Bookkeeping Services', 'Financial & Accounting Advisory', 'Keep your books accurate and up-to-date without the hassle — our team handles the day-to-day recording so you don''t have to.');
INSERT INTO services (code, name, service_line, description) VALUES ('FIN-005', 'CFO Services', 'Financial & Accounting Advisory', 'Let our expert team handle your company''s day-to-day financial operations so you can focus on growing your business.');
INSERT INTO services (code, name, service_line, description) VALUES ('MC-001', 'Organizational Design & Structure', 'Management Consulting', 'We help you design an organizational structure that supports your strategy, clarifies roles, and enables efficient decision-making.');
INSERT INTO services (code, name, service_line, description) VALUES ('MC-002', 'Job Architecture & Descriptions', 'Management Consulting', 'Clear, consistent job descriptions and a logical job architecture that makes hiring, promotion, and compensation decisions easier.');
INSERT INTO services (code, name, service_line, description) VALUES ('MC-003', 'Salary Grading & Benchmarking', 'Management Consulting', 'Ensure your compensation packages are competitive and fair with market-based salary grading and benchmarking.');
INSERT INTO services (code, name, service_line, description) VALUES ('MC-004', 'Board & Committee Charters', 'Management Consulting', 'We draft the governance documents that define how your board and committees operate, ensuring best-practice corporate governance.');
INSERT INTO services (code, name, service_line, description) VALUES ('MC-005', 'KPIs & Performance Systems', 'Management Consulting', 'Design performance measurement systems that align individual and team goals with your organization''s strategic objectives.');
INSERT INTO services (code, name, service_line, description) VALUES ('MC-006', 'Policies & Procedures Development', 'Management Consulting', 'We create clear, practical policies and procedures that your team will actually follow — reducing risk and improving consistency.');
INSERT INTO services (code, name, service_line, description) VALUES ('MC-007', 'Manpower & Training Plans', 'Management Consulting', 'Strategic workforce planning and training programs that ensure you have the right people with the right skills at the right time.');
INSERT INTO services (code, name, service_line, description) VALUES ('ESG-001', 'ESG Framework & Strategy', 'ESG Advisory', 'We help you develop a comprehensive ESG strategy that aligns with international standards and your business objectives.');
INSERT INTO services (code, name, service_line, description) VALUES ('ESG-002', 'ESG Reporting', 'ESG Advisory', 'Produce credible, transparent ESG reports that meet regulatory requirements and stakeholder expectations.');
INSERT INTO services (code, name, service_line, description) VALUES ('ESG-003', 'ESG Policies & Procedures', 'ESG Advisory', 'We create the policies and procedures you need to embed ESG principles into your daily operations and decision-making.');
INSERT INTO services (code, name, service_line, description) VALUES ('TRN-001', 'AML/CFT Training', 'Training & Development', 'Keep your team compliant and confident with practical anti-money laundering and counter-terrorism financing training.');
INSERT INTO services (code, name, service_line, description) VALUES ('TRN-002', 'Corporate Governance Programs', 'Training & Development', 'Equip your board members and executives with the knowledge and tools they need to govern effectively.');
INSERT INTO services (code, name, service_line, description) VALUES ('TRN-003', 'Custom Training Programs', 'Training & Development', 'Tailored training solutions designed around your organization''s specific needs, challenges, and industry requirements.');
